import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'elite' | 'neon';
  isLoading?: boolean;
}

const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-6 py-2 rounded-lg font-bold transition-all duration-300 transform hover:scale-[1.02] flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none";

  const variants = {
    primary: "bg-elite-magenta text-white shadow-lg hover:shadow-[0_0_20px_rgba(198,40,122,0.4)] border border-transparent",
    secondary: "bg-transparent text-elite-gold border border-elite-gold hover:bg-elite-gold hover:text-elite-black",
    danger: "bg-malandra text-white hover:bg-red-700",
    elite: "bg-gradient-to-r from-elite-purple to-elite-magenta text-white border border-elite-gold/30 hover:border-elite-gold shadow-elite hover:shadow-gold",
    neon: "bg-neon-azul text-black shadow-[0_0_15px_rgba(0,255,255,0.4)] border border-transparent hover:bg-white hover:shadow-neon-azul"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant] || variants.primary} ${className}`}
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <>
          <svg className="animate-spin -ml-1 mr-3 h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          <span className="tracking-widest text-xs uppercase">...</span>
        </>
      ) : children}
    </button>
  );
};

export default Button;

