      setDiagnosisMsg(`❌ Falla Sistémica: ${result.message}. Se recomienda reiniciar.`);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newAttachments: Attachment[] = [];
      Array.from(e.target.files).forEach(file => {
        newAttachments.push({
          file,
          previewUrl: URL.createObjectURL(file),
          type: file.type.startsWith('video') ? 'video' : file.type.startsWith('audio') ? 'audio' : 'image'
        });
      });
      setAttachments(prev => [...prev, ...newAttachments]);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && attachments.length === 0) || isLoading) return;
    if (health.status === 'critical') {
      alert("El sistema está en estado crítico. Esperando auto-diagnóstico...");
      return;
    }

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: Date.now(),
      attachments: [...attachments]
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setAttachments([]);
    setIsLoading(true);

    const config: ChatConfig = { mode, useSearch, aspectRatio };

    try {
      const responseMsgId = (Date.now() + 1).toString();
      let accumulatedText = "";

      setMessages(prev => [...prev, {
        id: responseMsgId,
        role: 'model',
        text: '',
        timestamp: Date.now(),
        isStreaming: true
      }]);

      const stream = streamChat(messages, userMsg.text, userMsg.attachments || [], config);

      for await (const chunk of stream) {
        if (chunk.text) accumulatedText += chunk.text;

        setMessages(prev => {
          const newMessages = [...prev];
          const lastMessage = newMessages[newMessages.length - 1];
          if (lastMessage?.id === responseMsgId) {
            lastMessage.text = accumulatedText;
            lastMessage.sources = chunk.sources || lastMessage.sources;
            lastMessage.generatedImages = chunk.images || lastMessage.generatedImages;
          }
          return newMessages;
        });
      }
      setMessages(prev => prev.map(msg => 
        msg.id === responseMsgId ? { ...msg, isStreaming: false } : msg
      ));
      setHealth(TelemetryMonitor.getCurrentHealth());

    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Error: Could not connect to Gemini Omni core.",
        timestamp: Date.now()
      }]);
      setHealth(TelemetryMonitor.getCurrentHealth());
    } finally {
      setIsLoading(false);
    }
  };

  const getHealthColor = () => {
    switch (health.status) {
      case 'stable': return 'text-elite-gold';
      case 'unstable': return 'text-orange-400';
      case 'critical': return 'text-red-500 animate-pulse';
      default: return 'text-gray-400';
    }
  };

  return (
    <div className="flex flex-col h-screen bg-elite-black text-slate-100 relative z-50 font-sans">
      <header className="px-6 py-4 bg-elite-black border-b border-white/10 flex flex-wrap gap-4 justify-between items-center shadow-lg sticky top-0 z-10">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-white/10 rounded-full text-elite-gold transition-colors">
            <span className="text-xl">←</span>
          </button>
          <div className="flex flex-col">
            <h1 className="text-2xl font-bold font-serif text-transparent bg-clip-text bg-gradient-to-r from-elite-purple to-elite-magenta tracking-wide">
              OMNI COMMAND
            </h1>
            <span className={`text-[10px] font-mono flex items-center gap-2 uppercase tracking-widest ${getHealthColor()}`}>
              <span className="w-2 h-2 rounded-full bg-current"></span>
              IEC: {health.iec} [{health.status}]
            </span>
          </div>
        </div>

        <div className="flex gap-1 bg-[#252525] p-1.5 rounded-xl border border-white/5">
          <button onClick={() => setMode('lightning')} className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${mode === 'lightning' ? 'bg-elite-gold text-black shadow-gold' : 'text-gray-500 hover:text-white'}`}>⚡ Fast</button>
          <button onClick={() => setMode('standard')} className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${mode === 'standard' ? 'bg-elite-purple text-white shadow-elite' : 'text-gray-500 hover:text-white'}`}>🧠 Core</button>
          <button onClick={() => setMode('pro')} className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${mode === 'pro' ? 'bg-elite-magenta text-white shadow-[0_0_15px_rgba(198,40,122,0.5)]' : 'text-gray-500 hover:text-white'}`}>🔮 Pro</button>
          <button onClick={() => setMode('image')} className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${mode === 'image' ? 'bg-fresa text-white shadow-[0_0_15px_rgba(59,178,115,0.4)]' : 'text-gray-500 hover:text-white'}`}>🎨 Art</button>
        </div>

        <div className="flex items-center gap-4">
          {mode === 'standard' && (
            <label className="flex items-center gap-2 cursor-pointer group">
              <input type="checkbox" checked={useSearch} onChange={e => setUseSearch(e.target.checked)} className="w-4 h-4 accent-elite-magenta cursor-pointer" />
              <span className="text-xs font-bold text-elite-gold group-hover:text-white transition-colors uppercase tracking-wider">Grounding</span>
            </label>
          )}
          {mode === 'image' && (
            <select value={aspectRatio} onChange={e => setAspectRatio(e.target.value)} className="bg-[#252525] border border-white/10 rounded-lg text-xs py-2 px-3 text-elite-gold focus:border-elite-gold outline-none cursor-pointer">
              <option value="1:1">1:1 Square</option>
              <option value="16:9">16:9 Landscape</option>
              <option value="9:16">9:16 Portrait</option>
              <option value="4:3">4:3 Standard</option>
            </select>
          )}
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
        {diagnosisMsg && (
          <div className="mx-auto max-w-lg p-4 bg-[#252525] border-l-2 border-elite-magenta rounded-r-lg shadow-elite animate-fade-in mb-4 flex items-center gap-3">
             <span className="animate-pulse text-xl">⚠️</span>
             <p className="text-xs font-mono text-gray-300 uppercase">{diagnosisMsg}</p>
          </div>
        )}

        {messages.length === 0 && (
          <div className="flex flex-col items-center justify-center h-[60vh] text-gray-600 opacity-30 select-none">
            <span className="text-8xl font-serif mb-4 filter blur-[1px]">OMNI</span>
            <p className="text-sm font-mono tracking-[0.5em] uppercase">Esperando Input</p>
          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-6 shadow-lg relative ${msg.role === 'user' ? 'bg-elite-magenta text-white rounded-br-none shadow-[0_5px_15px_rgba(198,40,122,0.3)]' : 'bg-[#252525] border border-elite-gold/10 text-gray-200 rounded-bl-none'}`}>
              {msg.role === 'model' && (
                <div className="absolute -top-3 left-0 bg-elite-black border border-elite-gold/30 px-2 py-0.5 rounded text-[10px] font-bold text-elite-gold uppercase tracking-wider">Magistral DecoX</div>
              )}

              {msg.attachments && msg.attachments.length > 0 && (
                <div className="flex gap-2 mb-4 overflow-x-auto pb-2">
                  {msg.attachments.map((att, i) => (
                    <div key={i} className="relative h-24 w-24 rounded-lg overflow-hidden border border-white/20 shadow-sm shrink-0">
                      {att.type === 'image' ? (
                        <img src={att.previewUrl} className="h-full w-full object-cover" alt="attachment" />
                      ) : (
                        <div className="h-full w-full bg-elite-black flex items-center justify-center text-xs text-gray-400 font-mono flex-col gap-1"><span className="text-xl">📎</span>{att.type}</div>
                      )}
                    </div>
                  ))}
                </div>
              )}

              <div className="whitespace-pre-wrap leading-relaxed text-sm md:text-base font-light">{msg.text}</div>
              {msg.generatedImages && msg.generatedImages.map((img, i) => (
                <div key={i} className="mt-4 rounded-xl overflow-hidden border-2 border-elite-gold/20 shadow-lg"><img src={img} alt="Generated" className="w-full h-auto hover:scale-105 transition-transform duration-700" /></div>
              ))}
              {msg.sources && msg.sources.length > 0 && (
                <div className="mt-4 pt-3 border-t border-white/10 flex flex-wrap gap-2">
                   {msg.sources.map((src, idx) => (
                     <a key={idx} href={src.uri} target="_blank" rel="noreferrer" className="text-[10px] bg-black/40 hover:bg-elite-gold/20 text-elite-gold border border-elite-gold/30 px-3 py-1.5 rounded-full transition-colors uppercase tracking-wider font-bold">🔗 {src.title || "Fuente Externa"}</a>
                   ))}
                </div>
              )}
              {msg.isStreaming && <div className="mt-3 flex items-center gap-2 text-elite-gold text-xs font-mono opacity-80"><div className="w-1.5 h-1.5 bg-elite-gold rounded-full animate-bounce"></div><div className="w-1.5 h-1.5 bg-elite-gold rounded-full animate-bounce delay-75"></div><div className="w-1.5 h-1.5 bg-elite-gold rounded-full animate-bounce delay-150"></div><span className="tracking-widest uppercase">Decodificando</span></div>}
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-6 bg-elite-black border-t border-white/5">
        {attachments.length > 0 && (
          <div className="flex gap-3 mb-4 p-3 bg-[#252525] rounded-xl border border-white/5 w-fit animate-fade-in">
            {attachments.map((att, i) => (
              <div key={i} className="relative group">
                <img src={att.previewUrl} className="h-12 w-12 rounded-lg object-cover border border-elite-gold/30" alt="preview"/>
                <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="absolute -top-2 -right-2 bg-malandra rounded-full w-5 h-5 flex items-center justify-center text-[10px] text-white opacity-0 group-hover:opacity-100 shadow-md transition-opacity">×</button>
              </div>
            ))}
          </div>
        )}
        <div className="flex gap-4 items-end max-w-5xl mx-auto">
          <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-[#252525] hover:bg-[#333] border border-white/10 rounded-xl text-elite-gold transition-all duration-300 hover:scale-105 hover:border-elite-gold" disabled={health.status === 'critical' || isLoading}><span className="text-xl">📎</span></button>
          <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileSelect} accept="image/*,video/*,audio/*" />
          <div className="flex-1 relative">
            <textarea value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }} placeholder={health.status === 'critical' ? "DIAGNÓSTICO EN CURSO..." : (mode === 'image' ? "Describe la visión a sintetizar..." : "Ingresa tu input estratégico...")} disabled={health.status === 'critical' || isLoading} className="w-full bg-[#252525] border border-white/10 rounded-xl px-5 py-4 text-white placeholder-gray-500 focus:outline-none focus:border-elite-gold focus:ring-1 focus:ring-elite-gold resize-none h-16 max-h-32 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-inner" />
            <div className="absolute bottom-2 right-3 text-[10px] text-gray-600 font-mono pointer-events-none uppercase">Omni V2.1 // Ready</div>
          </div>
          <Button onClick={handleSend} disabled={health.status === 'critical' || isLoading} variant="elite" className="h-16 w-20 !px-0 flex items-center justify-center rounded-xl"><span className="text-2xl">➤</span></Button>
        </div>
      </div>
    </div>
  );
};

