import React, { useState } from 'react';
import { ArchetypeKey } from '../../types';
import { ARCHETYPES } from '../../data/constants';

const QuizSection: React.FC = () => {
  const [q1, setQ1] = useState<ArchetypeKey | null>(null);
  const [q2, setQ2] = useState<ArchetypeKey | null>(null);
  const [result, setResult] = useState<{ title: string; text: string; color: string } | null>(null);
  const [error, setError] = useState<boolean>(false);

  const calculateResult = () => {
    // Feedback Loop: Validación de entrada
    if (!q1 || !q2) {
      setError(true);
      // Auto-reparación del estado de error después de 3 segundos
      setTimeout(() => setError(false), 3000);
      return;
    }

    setError(false);

    // Lógica de Matriz de Decisión (Algoritmo de Síntesis)
    const scores: Record<string, number> = { chola: 0, malandra: 0, fresa: 0, magistral: 0 };
    scores[q1] = (scores[q1] || 0) + 1;
    scores[q2] = (scores[q2] || 0) + 1;

    let dominant: ArchetypeKey = 'chola';

    // Heurística de Prioridad: Fresa (Síntesis) > Magistral (Motor) > Malandra (Antítesis) > Chola (Tesis)
    if (q1 === 'fresa' || q2 === 'fresa') dominant = 'fresa'; 
    else if (q1 === 'magistral' || q2 === 'magistral') dominant = 'magistral';
    else if (scores['malandra'] > 0) dominant = 'malandra';
    else dominant = 'chola';

    // Override Específico: La mezcla Chola + Fresa siempre resulta en Fresa (la aspiración gana)
    if ((q1 === 'chola' && q2 === 'fresa') || (q1 === 'fresa' && q2 === 'chola')) dominant = 'fresa';

    const archetype = ARCHETYPES[dominant];

    // Generación de Texto Dinámico
    let customText = "";
    let customTitle = "";

    switch(dominant) {
        case 'fresa':
            customTitle = "¡Fresa con alma de Cholita!";
            customText = "Tu síntesis te convierte en una Chalamandra X: posees la metodología y el buen gusto, pero necesitas ensuciarte los tacones en el terreno real.";
            break;
        case 'magistral':
            customTitle = "¡Magistral con Astucia!";
            customText = "Posees el algoritmo perfecto sin olvidar la calle. Tu código es inquebrantable y tu pedagogía es letal.";
            break;
        case 'malandra':
            customTitle = "¡Malandra de Corazón!";
            customText = "Ves el atajo antes que nadie. Tu estrategia es ágil, capaz de romper sistemas obsoletos y encontrar la puerta trasera.";
            break;
        default:
            customTitle = "¡Chola con Visión!";
            customText = "Resiliencia pura. Tienes la base más sólida de todas; ahora aplica el método SRAP para escalar esa supervivencia.";
    }

    setResult({
      title: customTitle,
      text: customText,
      color: archetype.color
    });
  };

  return (
    <div className="relative">
      <h2 className="text-4xl md:text-5xl font-bold text-center text-slate-900 font-serif">Test: ¿Dominas los 3 CÓDIGOS?</h2>
      <p className="text-xl text-slate-600 text-center max-w-3xl mx-auto mt-4">
        Descubre tu arquetipo dominante. Este algoritmo interactivo te ayuda a triangular tu posición en el universo Chalamandra.
      </p>

      <div className="mt-12 bg-white p-8 md:p-12 rounded-lg shadow-xl max-w-3xl mx-auto border border-slate-100 transition-all duration-300">

        {/* Pregunta 1: Herramientas */}
        <div className="mb-8">
          <h4 className="text-2xl font-bold mb-4 text-slate-800 font-serif">1. Tu arma secreta es...</h4>
          <div className="space-y-3">
            {[
              { val: 'chola', label: 'a) Una chancla. (Resiliencia)' },
              { val: 'fresa', label: 'b) Un stiletto. (Estética)' },
              { val: 'magistral', label: 'c) Un algoritmo. (Método)' }
            ].map(opt => (
              <label 
                key={opt.val} 
                className={`block p-4 border rounded-lg cursor-pointer text-lg transition-all duration-200 ${q1 === opt.val ? 'bg-indigo-50 border-magistral ring-1 ring-magistral shadow-md' : 'border-slate-300 hover:border-purple-400 hover:bg-slate-50'}`}
              >
                <input 
                  type="radio" 
                  name="q1" 
                  value={opt.val} 
                  className="sr-only" 
                  onChange={() => { setQ1(opt.val as ArchetypeKey); if(error) setError(false); }} 
                  checked={q1 === opt.val}
                />
                {opt.label}
              </label>
            ))}
          </div>
        </div>

        {/* Pregunta 2: Entorno */}
        <div className="mb-8">
          <h4 className="text-2xl font-bold mb-4 text-slate-800 font-serif">2. Tu campo de juego favorito es...</h4>
          <div className="space-y-3">
            {[
              { val: 'malandra', label: 'a) El mercado. (Astucia)' },
              { val: 'fresa', label: 'b) La junta directiva. (Estrategia)' },
              { val: 'magistral', label: 'c) La pista de baile / cyberespacio. (Disciplina)' }
            ].map(opt => (
              <label 
                key={opt.val} 
                className={`block p-4 border rounded-lg cursor-pointer text-lg transition-all duration-200 ${q2 === opt.val ? 'bg-indigo-50 border-magistral ring-1 ring-magistral shadow-md' : 'border-slate-300 hover:border-purple-400 hover:bg-slate-50'}`}
              >
                <input 
                  type="radio" 
                  name="q2" 
                  value={opt.val} 
                  className="sr-only" 
                  onChange={() => { setQ2(opt.val as ArchetypeKey); if(error) setError(false); }}
                  checked={q2 === opt.val}
                />
                {opt.label}
              </label>
            ))}
          </div>
        </div>

        <div className="space-y-4">
            <button 
              onClick={calculateResult}
              className="w-full text-white font-bold text-lg py-4 px-6 rounded-lg transition-all duration-300 hover:bg-orange-700 active:scale-95 shadow-lg transform hover:-translate-y-1 bg-malandra flex justify-center items-center"
            >
              Decodificar Mi Perfil
            </button>

            {/* Feedback Visual de Error */}
            <div className={`text-center p-3 rounded-lg bg-red-100 text-red-700 font-bold transition-all duration-300 ${error ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2 pointer-events-none absolute'}`}>
                ⚠️ Error de Input: Debes responder ambas preguntas para procesar el algoritmo.
            </div>
        </div>

        {result && (
          <div className="mt-8 p-8 rounded-lg text-center border animate-fade-in shadow-inner relative overflow-hidden" style={{ backgroundColor: `${result.color}10`, borderColor: result.color }}>
            <div className="relative z-10">
                <h4 className="text-3xl font-bold mb-3 font-serif" style={{ color: result.color }}>{result.title}</h4>
                <p className="text-lg text-slate-800 leading-relaxed">{result.text}</p>
            </div>
            {/* Elemento decorativo de fondo */}
            <div className="absolute top-0 right-0 w-32 h-32 opacity-10 rounded-full -mr-16 -mt-16" style={{ backgroundColor: result.color }}></div>
          </div>
        )}
      </div>
    </div>
  );
};

export default QuizSection;

