import React, { useState } from 'react';
import { DIAGNOSIS_QUESTIONS } from '../../data/constants';

const DiagnosisSection: React.FC = () => {
  const [responses, setResponses] = useState<Record<number, number>>({});
  const [finished, setFinished] = useState(false);
  const [email, setEmail] = useState('');
  const [leadCaptured, setLeadCaptured] = useState(false);

  const handleResponse = (id: number, val: number) => {
    setResponses(prev => ({ ...prev, [id]: val }));
  };

  const calculateScore = () => {
    setFinished(true);
  };

  const handleLeadCapture = () => {
    if(email.includes('@')) {
        setLeadCaptured(true);
    }
  };

  const score = (Object.values(responses) as number[]).reduce((a, b) => a + b, 0);
  const maxScore = DIAGNOSIS_QUESTIONS.length;
  const isComplete = DIAGNOSIS_QUESTIONS.every(q => responses[q.id] !== undefined);

  return (
    <div className="max-w-3xl mx-auto p-6">
      <div className="text-center mb-10">
        <h2 className="text-3xl md:text-4xl font-serif font-bold text-gray-900 mb-4">Diagnóstico: ¿Tu Firewall Está Activo?</h2>
        <p className="text-lg text-gray-500">Prueba de penetración emocional y resistencia a ataques de *malware* corporativo.</p>
      </div>

      {!finished ? (
        <div className="space-y-6 bg-white rounded-2xl shadow-xl p-8 border border-gray-100 transition-all duration-500">
          {DIAGNOSIS_QUESTIONS.map((q) => (
            <div key={q.id} className="pb-6 border-b border-gray-100 last:border-0 hover:bg-slate-50 p-4 rounded-lg transition-colors">
              <p className="font-bold text-gray-800 mb-4 text-lg font-serif">{q.id}. {q.text}</p>
              <div className="flex flex-col sm:flex-row gap-4">
                <button 
                  onClick={() => handleResponse(q.id, 1)}
                  className={`flex-1 p-4 rounded-xl border-2 transition-all duration-200 ${responses[q.id] === 1 ? 'border-red-500 bg-red-50 text-red-700 font-bold shadow-inner' : 'border-gray-200 hover:border-red-300 hover:bg-red-50/50'}`}
                >
                  Sí (Alerta de Intruso)
                </button>
                <button 
                  onClick={() => handleResponse(q.id, 0)}
                  className={`flex-1 p-4 rounded-xl border-2 transition-all duration-200 ${responses[q.id] === 0 ? 'border-magistral bg-purple-50 text-magistral font-bold shadow-inner' : 'border-gray-200 hover:border-magistral hover:bg-purple-50/50'}`}
                >
                  No (Firewall Activo)
                </button>
              </div>
            </div>
          ))}
          <button
            onClick={calculateScore}
            disabled={!isComplete}
            className="w-full bg-magistral text-white font-bold py-4 rounded-xl text-lg hover:bg-purple-900 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg mt-6"
          >
            {isComplete ? "Decodificar Resultados del Sistema" : "Completa todas las preguntas..."}
          </button>
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow-xl p-10 text-center animate-fade-in border-t-8 border-magistral">
          <h3 className="text-3xl font-bold mb-4 text-magistral font-serif">
            {score >= maxScore * 0.7 ? "¡ALERTA CRÍTICA! Firewall Comprometido." : 
             score >= maxScore * 0.4 ? "Sistema Inestable. Modo STANDBY." : 
             "Firewall Activo. ¡Bienvenido, Decodificador!"}
          </h3>

          <div className="my-6">
            <div className="w-full bg-gray-200 rounded-full h-4 mb-2 overflow-hidden">
                <div 
                    className={`h-4 rounded-full transition-all duration-1000 ${score >= maxScore * 0.7 ? 'bg-red-500' : score >= maxScore * 0.4 ? 'bg-yellow-400' : 'bg-green-500'}`}
                    style={{ width: `${(score / maxScore) * 100}%` }}
                ></div>
            </div>
            <p className="text-gray-600 text-lg font-medium">
                Nivel de Vulnerabilidad: {Math.round((score / maxScore) * 100)}%
            </p>
          </div>

          <p className="text-gray-600 mb-8 text-lg leading-relaxed">
            {score >= maxScore * 0.7 ? `Tu sistema está bajo un ataque DDoS emocional masivo. Tus puertos están abiertos y estás filtrando energía vital. Necesitas aplicar el protocolo SRAP de inmediato.` : 
             score >= maxScore * 0.4 ? `Tienes límites perimetrales, pero el núcleo es blando. Hay puertos abiertos que un hacker emocional experto (o un jefe tóxico) podría explotar.` : 
             `Tus protocolos son robustos. Detectas las amenazas antes de que ejecuten código malicioso. El reto ahora es el mantenimiento constante.`}
          </p>

          <div className={`bg-slate-50 p-6 rounded-xl border border-slate-200 inline-block w-full max-w-md transition-all duration-500 ${leadCaptured ? 'bg-green-50 border-green-200' : ''}`}>
            {!leadCaptured ? (
                <>
                    <p className="text-sm font-bold text-slate-500 uppercase mb-2 tracking-wide">Descarga el Parche de Seguridad</p>
                    <p className="text-slate-800 mb-4 font-bold">Recibe tu "Diagnóstico Completo" y el Ebook SRAP gratis.</p>
                    <div className="flex flex-col sm:flex-row gap-2">
                    <input 
                        type="email" 
                        placeholder="tu@email.com" 
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="flex-1 p-3 border border-slate-300 rounded-lg bg-white focus:outline-none focus:border-magistral" 
                    />
                    <button 
                        onClick={handleLeadCapture}
                        disabled={!email.includes('@')}
                        className="bg-fresa text-white px-6 py-3 rounded-lg font-bold hover:bg-emerald-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        Enviar
                    </button>
                    </div>
                </>
            ) : (
                <div className="animate-fade-in py-4">
                    <span className="text-4xl mb-2 block">✅</span>
                    <p className="font-bold text-green-800 text-lg">¡Enviado!</p>
                    <p className="text-green-700 text-sm">Revisa tu bandeja de entrada. El código ha sido transferido.</p>
                </div>
            )}
          </div>

          <button onClick={() => {setFinished(false); setResponses({}); setLeadCaptured(false); setEmail('');}} className="block mx-auto mt-8 text-gray-400 hover:text-magistral font-bold hover:underline transition-colors text-sm">
            Reiniciar Diagnóstico
          </button>
        </div>
      )}
    </div>
  );
};

export default DiagnosisSection;

