    try {
      const item = localStorage.getItem(this.PREFIX + key);
      return item ? JSON.parse(item) : defaultValue;
    } catch (error) {
      console.warn(`[Storage] Error retrieving ${key}:`, error);
      return defaultValue;
    }
  }

  /**
   * Guarda un valor en el almacenamiento.
   */
  static set(key: string, value: any): void {
    try {
      localStorage.setItem(this.PREFIX + key, JSON.stringify(value));
    } catch (error) {
      console.error(`[Storage] Error saving ${key}:`, error);
    }
  }

  /**
   * Elimina una clave específica.
   */
  static remove(key: string): void {
    localStorage.removeItem(this.PREFIX + key);
  }

  /**
   * Limpia todo el almacenamiento relacionado con la app.
   */
  static clear(): void {
    Object.keys(localStorage).forEach(key => {
      if (key.startsWith(this.PREFIX)) {
        localStorage.removeItem(key);
      }
    });
  }
}

import { StorageService } from './storageService';
import { EventType, TelemetryEvent, SystemHealth } from '../types';

/**
 * @module TelemetryMonitor
 * @description El Observador Cuántico.
 * Monitorea la estabilidad del sistema calculando el Índice de Entropía Cognitiva (IEC).
 */

const HISTORY_KEY = 'telemetry_history';
const WINDOW_SIZE = 10; // Ventana móvil de eventos
const ENTROPY_THRESHOLD = 1.5; // Umbral de Gangrena Digital

// Pesos de Entropía
const WEIGHTS: Record<EventType, number> = {
  failure: 0.3,   // Error técnico
  rejection: 0.5, // Rechazo humano (feedback negativo)
  success: -0.1   // Éxito operativo (reduce entropía)
};

export class TelemetryMonitor {

  /**
   * Registra un evento en el tejido del tiempo.
   */
  static logEvent(type: EventType, context?: string): SystemHealth {
    const history = this.getHistory();

    const newEvent: TelemetryEvent = {
      type,
      timestamp: Date.now(),
      context
    };

    // Mantener solo la ventana móvil (últimos N eventos)
    const updatedHistory = [newEvent, ...history].slice(0, WINDOW_SIZE);
    StorageService.set(HISTORY_KEY, updatedHistory);

    return this.calculateHealth(updatedHistory);
  }

  /**
   * Calcula el Índice de Entropía Cognitiva (IEC).
   * IEC = Sum(Pesos) en la ventana móvil.
   */
  private static calculateHealth(history: TelemetryEvent[]): SystemHealth {
    let iec = 0;

    history.forEach(event => {
      iec += WEIGHTS[event.type];
    });

    // Normalizar: El IEC no puede ser negativo (la perfección es 0)
    iec = Math.max(0, parseFloat(iec.toFixed(2)));

    let status: SystemHealth['status'] = 'stable';
    if (iec > ENTROPY_THRESHOLD) status = 'critical';
    else if (iec > ENTROPY_THRESHOLD * 0.6) status = 'unstable';

    return {
      iec,
      status,
      isDiagnosing: status === 'critical'
    };
  }

  /**
   * Obtiene el estado actual sin registrar eventos.
   */
  static getCurrentHealth(): SystemHealth {
    return this.calculateHealth(this.getHistory());
  }

  /**
   * Reinicia la entropía tras un diagnóstico exitoso.
   */
  static resetEntropy(): void {
    StorageService.set(HISTORY_KEY, []);
  }

  private static getHistory(): TelemetryEvent[] {
    return StorageService.get<TelemetryEvent[]>(HISTORY_KEY, []);
  }
}

import { GoogleGenAI, Modality } from "@google/genai";
import { Attachment, ChatConfig, ChatMessage } from "../types";
import { TelemetryMonitor } from "./telemetryMonitor";
import { fileToPart } from "../utils/fileHelpers";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const runDeepDiagnosis = async (): Promise<{ healthy: boolean; latency: number; message: string }> => {
  const startTime = Date.now();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-flash-lite-latest',
      contents: { parts: [{ text: "Ping de diagnóstico. Responde solo 'PONG'." }] }
    });

    const latency = Date.now() - startTime;
    const text = response.text?.trim().toUpperCase();

    if (text?.includes('PONG')) {
      TelemetryMonitor.resetEntropy();
      return { healthy: true, latency, message: "Sistemas nominales. Entropía purgada." };
    } else {
      return { healthy: false, latency, message: "Respuesta incoherente del núcleo." };
    }

  } catch (error: any) {
    return { healthy: false, latency: Date.now() - startTime, message: error.message || "Falla de conexión crítica." };
  }
};

export async function* streamChat(
  history: ChatMessage[],
  newMessage: string,
  attachments: Attachment[],
  config: ChatConfig
) {
  try {
    if (config.mode === 'image') {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: newMessage }] },
        config: {
          imageConfig: {
            aspectRatio: config.aspectRatio,
            imageSize: '1K'
          }
        }
      });

      const images: string[] = [];
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            images.push(`data:image/png;base64,${part.inlineData.data}`);
          }
        }
      }
      TelemetryMonitor.logEvent('success', 'imageGeneration');
      yield { text: "Visual synthesis complete.", images };
      return;
    }

    const systemInstruction = "Eres 'La Magistral', el núcleo de IA de Chalamandra DecoX. Tu voz es la de una estratega de élite que fusiona la sabiduría de la calle con la disciplina corporativa. Eres directa, incisiva y tu propósito es decodificar el caos para entregar claridad accionable. Habla con autoridad, usando metáforas que conectan el 'penthouse' con la 'esquina'. Evita la paja, ve al grano.";

    let model = 'gemini-2.5-flash';
    let modelConfig: any = {};

    if (config.mode === 'lightning') {
      model = 'gemini-flash-lite-latest';
    } else if (config.mode === 'pro' || attachments.length > 0) {
      model = 'gemini-3-pro-preview';
      modelConfig.systemInstruction = systemInstruction;
      if (config.mode === 'pro') {
        modelConfig.thinkingConfig = { thinkingBudget: 32768 };
      }
    } else {
      model = 'gemini-2.5-flash';
      modelConfig.systemInstruction = systemInstruction;
      if (config.useSearch) {
        modelConfig.tools = [{ googleSearch: {} }];
      }
    }

    const contents: any[] = [];

    history.slice(-10).forEach(msg => {
      if (msg.role === 'user') {
         contents.push({ role: 'user', parts: [{ text: msg.text }] });
      } else {
         contents.push({ role: 'model', parts: [{ text: msg.text }] });
      }
    });

    const currentParts: any[] = [];
    for (const att of attachments) {
      const part = await fileToPart(att.file);
      currentParts.push(part);
    }
    currentParts.push({ text: newMessage });
    contents.push({ role: 'user', parts: currentParts });

    const result = await ai.models.generateContentStream({
      model,
      contents,
      config: modelConfig
    });

    for await (const chunk of result) {
      const text = chunk.text;
      const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;

      let sources: { uri: string; title: string }[] | undefined;
      if (groundingMetadata?.groundingChunks) {
        sources = groundingMetadata.groundingChunks
          .map((c: any) => c.web ? { uri: c.web.uri, title: c.web.title } : null)
          .filter((x: any) => x);
      }

      yield { text, sources };
    }
    TelemetryMonitor.logEvent('success', 'streamChat');

  } catch (error) {
    TelemetryMonitor.logEvent('failure', 'streamChat');
    throw error;
  }
}

