      performAutoDiagnosis();
    }
  }, [health.status]);

  const performAutoDiagnosis = async () => {
    setDiagnosisMsg("⚠️ Entropía Crítica detectada. Iniciando Auto-Diagnóstico de Sistemas...");
    setIsLoading(true);
    const result = await runDeepDiagnosis();
    setIsLoading(false);
    if (result.healthy) {
      setDiagnosisMsg(`✅ Diagnóstico Exitoso. Latencia: ${result.latency}ms. Sistemas nominales.`);
      setHealth(TelemetryMonitor.getCurrentHealth()); 
